            setProjectName={touch(setProjectName)}
            models={models}
            labeledHarnesses={labeledHarnesses}
            defaultModel={defaultModel}
            onDefaultModelChange={(val) => {
              defaultModelTouchedRef.current = true;
              markDirty();
              setDefaultModel(val);
